# Run from the repository root with the project venv active, with the ai extra installed so the
# language model providers are bundled (pip install -e ".[ai]"); output goes to dist\labcatalog\.
# The scientific packages go in whole, since the program also runs the lab's Python scripts.
# PyInstaller itself, as nicegui-pack does, since nicegui-pack passes on no further options.
$nicegui = python -c "import nicegui, pathlib; print(pathlib.Path(nicegui.__file__).parent)"
pyinstaller --onedir --windowed --noconfirm --name labcatalog --add-data "$nicegui;nicegui" --icon src/labcatalog/gui/assets/icon.ico --add-data "src/labcatalog/blank.yaml;labcatalog" --add-data "src/labcatalog/example;labcatalog/example" --add-data "src/labcatalog/gui/theme.css;labcatalog/gui" --add-data "src/labcatalog/gui/network_graph.js;labcatalog/gui" --add-data "src/labcatalog/gui/banner_art.js;labcatalog/gui" --add-data "src/labcatalog/gui/assets;labcatalog/gui/assets" --add-data "src/labcatalog/gui/vendor;labcatalog/gui/vendor" --add-data "src/labcatalog/stats/cfa.R;labcatalog/stats" --add-data "src/labcatalog/stats/invariance.R;labcatalog/stats" --add-data "src/labcatalog/vocabularies;labcatalog/vocabularies" --collect-submodules pandas --collect-submodules numpy --collect-submodules scipy --collect-submodules statsmodels --collect-submodules semopy --collect-all matplotlib packaging/app.py
